Object.entries(batch5Roles).forEach(([role, [description, stages]]) => {
  roadmaps[role] = makeBatch5Roadmap(role, description, `batch5-${role.toLowerCase().replace(/[^a-z0-9]+/g, "-")}`, stages);
});

// Batch 6 uses distinct role outcomes while keeping the established roadmap schema.
const makeBatch6Roadmap = (role, description, prefix, rows) => ({
  title: `${role} Roadmap`, description,
  stages: rows.map(([stageTitle, missionTitle, outcome, skills], index) => ({
    title: stageTitle,
    description: outcome,
    mission: {
      title: missionTitle,
      description: outcome,
      why: `Demonstrate ${role.toLowerCase()} practice through a reviewable artifact and evidence.`,
      tasks: [`Define requirements and success checks for ${missionTitle.toLowerCase()}`, `Build and validate ${outcome.toLowerCase()}`, "Publish the artifact with test evidence, decisions, and limitations"],
      ...(index === 7 ? { finalMilestone: `${role} Portfolio Capstone` } : {})
    },
    skills: skills.map(([id, title, what, url, type]) => skill(
      `${prefix}-${id}`, title, what,
      `Study the linked resource and apply ${title.toLowerCase()} in a safe, small-scale project.`,
      `Create a focused exercise demonstrating ${title.toLowerCase()}; record expected behavior, observed results, and one limitation.`,
      [resource(`${title} learning resource`, url, type, what)]
    ))
  }))
});

