  // Keep the original curriculum rows concise while giving each skill a small,
  // relevant choice of formats. All additions reuse the renderer's resource shape.
  const supplementalResources = (skillTitle, role) => {
    const title = skillTitle.toLowerCase();
    if (/javascript|async|dom|fetch|react|html|css|responsive|frontend/.test(title)) return [
      resource("MDN Learn Web Development", "https://developer.mozilla.org/en-US/docs/Learn_web_development", "course", "Structured beginner-to-intermediate lessons with practical skill checks."),
      ...( /javascript|async|dom|fetch/.test(title) ? [resource("JavaScript: Full Course for Beginners (freeCodeCamp)", "https://www.youtube.com/watch?v=PkZNo7MFNFg", "video", "A guided beginner course covering core JavaScript concepts.")] : [])
    ];
    if (/python/.test(title)) return [
      resource("Python Tutorial", "https://docs.python.org/3/tutorial/", "documentation", "The official Python tutorial and language examples."),
      resource("Python for Beginners (freeCodeCamp)", "https://www.youtube.com/watch?v=rfscVS0vtbw", "video", "A free, structured introduction to Python programming.")
    ];
    if (/sql|database|query|relational/.test(title)) return [
      resource("SQLBolt Interactive Lessons", "https://sqlbolt.com/", "interactive", "Practice SQL queries directly in short interactive lessons.")
    ];
    if (/git|github|version control|pull request|branch/.test(title)) return [
      resource("GitHub Skills", "https://skills.github.com/", "interactive", "Learn GitHub workflows through hands-on exercises.")
    ];
    if (/web security|cross.site|injection|vulnerab|ethical hack|penetration|burp/.test(title)) return [
      resource("PortSwigger Web Security Academy", "https://portswigger.net/web-security", "practice", "Free, legal web security learning materials and interactive labs.")
    ];
    if (/security|authentication|authorization|cryptograph|identity|access control/.test(title)) return [
      resource("OWASP Top 10", "https://owasp.org/www-project-top-ten/", "documentation", "A widely used overview of common web application security risks.")
    ];
    if (/machine learning|model|neural|deep learning|artificial intelligence|\bai\b|feature engineering/.test(title)) return [
      resource("Google Machine Learning Crash Course", "https://developers.google.com/machine-learning/crash-course", "course", "Free modules combine explanations, videos, interactive visualizations, and exercises.")
    ];
    if (/docker|container/.test(title)) return [
      resource("Docker Get Started", "https://docs.docker.com/get-started/", "documentation", "Official hands-on introduction to building and running containers.")
    ];
    if (/kubernetes|orchestrat/.test(title)) return [
      resource("Kubernetes Basics Tutorial", "https://kubernetes.io/docs/tutorials/kubernetes-basics/", "interactive", "Walk through deploying, scaling, updating, and debugging an app.")
    ];
    if (/android|kotlin|jetpack compose/.test(title) || (/Mobile App Developer/.test(role) && /app|mobile|platform|interface|architecture/.test(title))) return [
      resource("Android Developer Codelabs", "https://developer.android.com/get-started/codelabs", "practice", "Guided, hands-on coding exercises from Android Developers.")
    ];
    if (/flutter|dart/.test(title) || /Flutter Developer/.test(role)) return [
      resource("Flutter Codelabs", "https://docs.flutter.dev/codelabs", "practice", "Build small Flutter apps through guided exercises.")
    ];
    if (/swift|ios|swiftui/.test(title) || /iOS Developer/.test(role)) return [
      resource("Apple SwiftUI Tutorials", "https://developer.apple.com/tutorials/swiftui", "course", "Apple's guided SwiftUI lessons and sample projects.")
    ];
    if (/api|http|rest|postman/.test(title)) return [
      resource("Postman Learning Center", "https://learning.postman.com/", "course", "Learn to send, inspect, and document API requests with Postman.")
    ];
    if (/network|tcp|ip address|routing|dns|firewall/.test(title)) return [
      resource("Cisco Networking Basics", "https://www.netacad.com/courses/networking-basics", "course", "Cisco Networking Academy's introductory networking course.")
    ];
    if (/data|analytics|statistics|visualization|pandas|numpy|spreadsheet|dashboard|business intelligence/.test(title)) return [
      resource("Kaggle Learn", "https://www.kaggle.com/learn", "interactive", "Short practical lessons and exercises for data and machine learning topics.")
    ];
    if (/test|quality assurance|automation|playwright|selenium/.test(title)) return [
      resource("Playwright Documentation", "https://playwright.dev/docs/intro", "documentation", "Official guide to writing and running browser tests.")
    ];
    if (/cloud|aws|azure|infrastructure|terraform|devops|site reliability|sre/.test(title)) return [
      resource("Google Cloud Training", "https://cloud.google.com/learn/training", "course", "Official training catalog with hands-on learning options; availability varies by lab.")
    ];
    if (/linux|shell|command line/.test(title)) return [
      resource("Ubuntu Server Documentation", "https://ubuntu.com/server/docs", "documentation", "Official guidance for common Linux server tasks.")
    ];
    return [];
  };
  const inferResourceType = (item) => {
    if (item.type) {
      const legacy = item.type.toLowerCase();
      if (["video", "article", "course", "interactive", "documentation", "practice", "tool"].includes(legacy)) return legacy;
      if (legacy === "tutorial") return /learn\.|course|academy|freecodecamp|kaggle|training/i.test(`${item.title} ${item.url}`) ? "course" : "article";
    }
    const source = `${item.title || item.name} ${item.url}`.toLowerCase();
    if (/youtube|video/.test(source)) return "video";
    if (/sqlbolt|skills\.github|codelab|interactive|playground|kubernetes-basics/.test(source)) return "interactive";
    if (/academy|course|freecodecamp|kaggle|training|learn\.microsoft/.test(source)) return "course";
    if (/practice|lab/.test(source)) return "practice";
    if (/tool|postman|playwright/.test(source)) return "tool";
    if (/article|blog|guide|tutorial/.test(source)) return "article";
    return "documentation";
  };
